#!/usr/bin/env python3
"""Control-coverage mapper: map check outcomes to control coverage status."""
import json
import sys

import yaml

COVERED, FAILING, UNCOVERED = "covered", "failing", "uncovered"


def load(path):
    with open(path) as f:
        return yaml.safe_load(f)


def report(mapping, results):
    """Return ({control: status}, errors). Unknown checks in results are errors."""
    controls = mapping["controls"]
    checks = mapping["checks"]
    errors = []
    for check in results:
        if check not in checks:
            errors.append(f"unknown check: {check}")
    status = {}
    for control in controls:
        evidencing = sorted(c for c, ctrls in checks.items() if control in ctrls)
        if not evidencing:
            status[control] = UNCOVERED
        elif any(results.get(c) == "pass" for c in evidencing):
            status[control] = COVERED
        else:
            status[control] = FAILING
    return status, errors


def main():
    mapping = load(sys.argv[1])
    with open(sys.argv[2]) as f:
        results = json.load(f)
    status, errors = report(mapping, results)
    for err in errors:
        print(f"error: {err}", file=sys.stderr)
    print(json.dumps(status, indent=2))
    return 1 if errors or any(s != COVERED for s in status.values()) else 0


if __name__ == "__main__":
    sys.exit(main())

