"""Tests: covered / failing / uncovered states, exit codes, unknown-check error."""
import json
import subprocess
import sys

import yaml

COV = [sys.executable, "coverage.py"]
MAP = {
    "controls": ["AC-1", "AC-2", "CM-1", "IR-1", "IR-2"],
    "checks": {
        "lockfile_check": ["CM-1"],
        "review_check": ["AC-1", "AC-2"],
        "oncall_check": ["IR-1"],
    },
}


def run(mapping, results, tmp_path):
    mpath = tmp_path / "mapping.yaml"
    rpath = tmp_path / "results.json"
    mpath.write_text(yaml.safe_dump(mapping))
    rpath.write_text(json.dumps(results))
    proc = subprocess.run(COV + [str(mpath), str(rpath)], capture_output=True, text=True)
    return proc


def test_all_covered(tmp_path):
    results = {"lockfile_check": "pass", "review_check": "pass", "oncall_check": "pass"}
    proc = run(MAP, results, tmp_path)
    assert json.loads(proc.stdout) == {
        "AC-1": "covered", "AC-2": "covered", "CM-1": "covered",
        "IR-1": "covered", "IR-2": "uncovered",
    }
    assert proc.returncode == 0 is False  # IR-2 uncovered -> nonzero
    assert proc.returncode != 0


def test_failing(tmp_path):
    results = {"lockfile_check": "fail", "review_check": "pass", "oncall_check": "fail"}
    proc = run(MAP, results, tmp_path)
    assert json.loads(proc.stdout) == {
        "AC-1": "covered", "AC-2": "covered", "CM-1": "failing",
        "IR-1": "failing", "IR-2": "uncovered",
    }
    assert proc.returncode == 1


def test_all_fail(tmp_path):
    results = {"lockfile_check": "fail", "review_check": "fail", "oncall_check": "fail"}
    proc = run(MAP, results, tmp_path)
    assert json.loads(proc.stdout) == {
        "AC-1": "failing", "AC-2": "failing", "CM-1": "failing",
        "IR-1": "failing", "IR-2": "uncovered",
    }
    assert proc.returncode == 1


def test_full_coverage_exit_zero(tmp_path):
    mapping = dict(MAP, checks={**MAP["checks"], "ir2_check": ["IR-2"]})
    results = {c: "pass" for c in mapping["checks"]}
    proc = run(mapping, results, tmp_path)
    assert json.loads(proc.stdout) == {
        "AC-1": "covered", "AC-2": "covered", "CM-1": "covered",
        "IR-1": "covered", "IR-2": "covered",
    }
    assert proc.returncode == 0
    assert proc.stderr == ""


def test_unknown_check_in_results_is_error(tmp_path):
    results = {"lockfile_check": "pass", "review_check": "pass",
               "oncall_check": "pass", "bogus_check": "pass"}
    proc = run(MAP, results, tmp_path)
    assert proc.returncode == 1
    assert "unknown check: bogus_check" in proc.stderr

